import{_ as a,o as c,c as h,j as n,a as i}from"./chunks/framework.CsGesDJn.js";const k=JSON.parse('{"title":"Package, campaign và task","description":"","frontmatter":{},"headers":[],"relativePath":"feature/package-driven-campaign-tasks/spec.md","filePath":"feature/package-driven-campaign-tasks/spec.md"}'),e={name:"feature/package-driven-campaign-tasks/spec.md"};function g(s,t,r,u,o,l){return c(),h("div",null,[...t[0]||(t[0]=[n("h1",{id:"package-campaign-va-task",tabindex:"-1"},[i("Package, campaign và task "),n("a",{class:"header-anchor",href:"#package-campaign-va-task","aria-label":'Permalink to "Package, campaign và task"'},"​")],-1),n("p",null,"Owner tạo gói mẫu cho Agency. Client chọn gói mẫu hoặc trao đổi để Manager tạo/chỉnh gói custom. Manager không cần Owner duyệt gói custom. Một gói chọn từ một đến bốn dịch vụ (bài đăng, workshop, event, báo điện tử). Mỗi loại có một dòng, mở phần nhập số lượng, mô tả, tiêu chí khi chọn. Hệ thống lưu tiêu chí để người duyệt đánh giá.",-1),n("p",null,"Ngay khi package được cả hai bên duyệt chốt, backend tự tạo một campaign DRAFT và đủ task lớn theo từng dòng dịch vụ trong luồng duyệt. Web chỉ đọc campaign đã tạo, không gọi /prepare. Form đặt ngày bắt đầu mặc định là ngày hiện tại. Manager có thể bổ sung thông tin task và tạo/chỉnh subtask trong Đầu việc dự kiến. Số task lớn giữ theo package. Agency và Client duyệt campaign theo luồng hiện tại. Thành viên bắt đầu làm task khi campaign IN_PROGRESS. Manager được hủy task lớn. Client dùng Content Request để yêu cầu việc mới, không tự sinh task thay thế.",-1),n("p",null,"Subtask một cấp, có người phụ trách, deadline, trạng thái và supervisor. Supervisor mặc định theo người phụ trách hiện tại của cha. Manager có thể gán supervisor riêng. Client xem được subtask. Thành viên có quyền thao tác chuyển giữa To Do, In Progress và In Review. Supervisor kế thừa quyền đó và được chuyển sang Done hoặc Cancelled. Manager kế thừa quyền supervisor. In Review là tùy chọn. Task cha được gửi approval circle khi mọi subtask đã Done hoặc Cancelled và hoàn thành theo approval circle hiện tại.",-1),n("p",null,"Tạo và đề xuất điều chỉnh package đều có lựa chọn nhanh cho thời lượng, ngân sách, số lượng. Phạm vi, mô tả và tiêu chí có mẫu và lựa chọn Khác. Đơn vị hiển thị cạnh nhãn số lượng. Gói không giới hạn số lần đề xuất thay đổi. Campaign có mẫu chiến lược và lựa chọn Khác, bỏ trường hướng dẫn thương hiệu trên web. Giao diện duyệt nêu chính xác các trường thiếu. Hỗ trợ vi/en, light/dark, tải, lỗi, trống và thiếu quyền.",-1),n("p",null,"Campaign chỉ được đóng khi thỏa điều kiện hiện có và tất cả Content Request đã nhận thuộc campaign đã xử lý xong. Request ở trạng thái ACCEPTED được xem là đã xử lý khi task sinh từ request ở Done hoặc Cancelled. Request đã nhận còn dang dở chặn đóng campaign, kể cả khi tất cả task lớn từ package đã kết thúc.",-1),n("p",null,"Phạm vi dừng ở package, campaign, task và subtask. Post/event/workshop tiếp tục gắn với task lớn. Mô hình, nghiệp vụ và đầu ra từng dịch vụ thuộc phần của các thành viên khác.",-1),n("p",null,"Task lớn mới tạo được gán cả người thực hiện và người giám sát cho Manager. Manager có thể đổi từng trường sang thành viên nội bộ đang hoạt động trong workspace. Subtask cũng chỉ được gán cho thành viên nội bộ đang hoạt động trong workspace. Khi người thực hiện đồng thời là người giám sát, bỏ qua bước duyệt nội bộ; vẫn giữ bước duyệt Client nếu được yêu cầu. Bài đăng phải được duyệt trước khi chuyển sang trạng thái lên lịch; tác vụ xuất bản không được tự hoàn thành task chưa được duyệt.",-1)])])}const v=a(e,[["render",g]]);export{k as __pageData,v as default};
